package com.campus.service; import com.campus.common.Paging;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.util.*;
@Service public class DeliveryService {private final JdbcTemplate db;private final PlatformSettingService settings;public DeliveryService(JdbcTemplate d,PlatformSettingService ps){db=d;settings=ps;}private static final Set<String> FLOW=Set.of("WAITING","ACCEPTED","PICKED_UP","DELIVERING","COMPLETED","CANCELLED");
 public Map<String,Object> create(long uid,long trade,String type,String pickup,String delivery){if(!Set.of("EXPRESS","ERRAND","FOOD").contains(type))throw new IllegalArgumentException("配送类型无效");var x=db.queryForList("SELECT buyer_id,seller_id,status FROM trade_order WHERE id=?",trade);if(x.isEmpty())throw new IllegalArgumentException("交易订单不存在");var r=x.get(0);long buyer=((Number)r.get("buyer_id")).longValue(),seller=((Number)r.get("seller_id")).longValue();if(uid!=buyer&&uid!=seller)throw new IllegalArgumentException("无权创建配送");if(!"PAID".equals(r.get("status")))throw new IllegalArgumentException("交易订单尚未支付");if(pickup==null||pickup.isBlank()||delivery==null||delivery.isBlank())throw new IllegalArgumentException("请填写配送地址");if(db.queryForObject("SELECT COUNT(*) FROM delivery_order WHERE trade_order_id=? AND status NOT IN ('CANCELLED','COMPLETED')",Integer.class,trade)>0)throw new IllegalArgumentException("该交易已有配送订单");BigDecimal fee=new BigDecimal(settings.get("delivery.fee","5.00")),pf=fee.multiply(new BigDecimal(settings.get("delivery.platformRate","0.15"))).setScale(2,RoundingMode.HALF_UP);String no="DEL"+UUID.randomUUID().toString().replace("-","");db.update("INSERT INTO delivery_order(delivery_no,trade_order_id,delivery_type,sender_id,receiver_id,pickup_location,delivery_location,fee,platform_fee) VALUES(?,?,?,?,?,?,?,?,?)",no,trade,type,seller,buyer,pickup,delivery,fee,pf);return one(db.queryForObject("SELECT id FROM delivery_order WHERE delivery_no=?",Long.class,no));}
 private Map<String,Object> one(long id){return db.queryForMap("SELECT d.*,t.order_no tradeOrderNo FROM delivery_order d JOIN trade_order t ON t.id=d.trade_order_id WHERE d.id=?",id);}
 public Map<String,Object> get(long uid,long id){var x=one(id);if(!Objects.equals(((Number)x.get("sender_id")).longValue(),uid)&&!Objects.equals(((Number)x.get("receiver_id")).longValue(),uid))throw new IllegalArgumentException("配送订单不存在");return x;}
 public Map<String,Object> list(long uid,int page,int size){var p=new Paging(page,size);String w=" WHERE sender_id=? OR receiver_id=?";return Map.of("records",db.queryForList("SELECT * FROM delivery_order"+w+" ORDER BY created_at DESC,id DESC "+p.limit(),uid,uid),"total",db.queryForObject("SELECT COUNT(*) FROM delivery_order"+w,Long.class,uid,uid),"page",p.page(),"size",p.size());}
 public Map<String,Object> adminList(int page,int size,String type){var p=new Paging(page,size);String filter=type==null||type.isBlank()?"":" WHERE delivery_type=?"; Object[] args=filter.isEmpty()?new Object[]{}:new Object[]{type}; return Map.of("records",db.queryForList("SELECT * FROM delivery_order"+filter+" ORDER BY created_at DESC,id DESC "+p.limit(),args),"total",db.queryForObject("SELECT COUNT(*) FROM delivery_order"+filter,Long.class,args),"page",p.page(),"size",p.size());}
 @Transactional public Map<String,Object> transition(long uid,long id,String next){var x=one(id);long sender=((Number)x.get("sender_id")).longValue(),receiver=((Number)x.get("receiver_id")).longValue();String cur=(String)x.get("status");boolean allowed=(uid==sender&&Set.of("CANCELLED","PICKED_UP").contains(next))||(uid==receiver&&Set.of("ACCEPTED","DELIVERING","COMPLETED").contains(next));if(!allowed||!FLOW.contains(next))throw new IllegalArgumentException("无权执行该配送状态变更");if(!valid(cur,next))throw new IllegalArgumentException("配送状态流转无效");db.update("UPDATE delivery_order SET status=?,completed_at=CASE WHEN ?='COMPLETED' THEN NOW() ELSE completed_at END WHERE id=? AND status=?",next,next,id,cur);return one(id);}
 private boolean valid(String a,String b){return (a.equals("WAITING")&&(b.equals("ACCEPTED")||b.equals("CANCELLED")))||(a.equals("ACCEPTED")&&(b.equals("PICKED_UP")||b.equals("CANCELLED")))||(a.equals("PICKED_UP")&&b.equals("DELIVERING"))||(a.equals("DELIVERING")&&b.equals("COMPLETED"));}
 public Map<String,Object> stats(){return db.queryForMap("SELECT COUNT(*) orders,COALESCE(SUM(fee),0) fees,COALESCE(SUM(platform_fee),0) platformFees,SUM(status='COMPLETED') completed FROM delivery_order");}
}

